import math

def f(n):
    result = []
    for i in range(1, n+1):
        if i % 2 == 0:
            result.append(math.factorial(i))
        else:
            result.append(sum(range(1, i+1))
    return result

# Test the function
print(f(5))  # Output should be [1, 2, 6, 24, 15]

